function deskList(key) {
  checkKey_(key);
  // 加速：每個案件資料夾只列一次檔案，需要的才讀；已送出的案件放快取（6 小時）；45 天前的案件不列
  const out = [], it = deskRoot_().getFolders(), cache = CacheService.getScriptCache();
  const cutoff = Utilities.formatDate(new Date(Date.now() - 45 * 864e5), CONFIG.TZ, 'yyyyMMdd');
  while (it.hasNext()) {
    const f = it.next(), fname = f.getName();
    if (/^\d{8}/.test(fname) && fname.slice(0, 8) < cutoff) continue;
    const ck = 'dk2_' + f.getId(), hit = cache.get(ck);
    if (hit) { try { out.push(JSON.parse(hit)); continue; } catch (e) {} }
    const map = {}, names = [], fi = f.getFiles();
    while (fi.hasNext()) { const x = fi.next(), n = x.getName(); if (!map[n]) map[n] = x; names.push(n); }
    const T = function (n) { return map[n] ? map[n].getBlob().getDataAsString('UTF-8') : ''; };
    const J = function (n) { if (!map[n]) return null; try { return JSON.parse(T(n)); } catch (e) { return null; } };
    const meta = J('案件.json'); if (!meta) continue;
    let st = map['已送出.json'] ? 'sent' : map['草稿.json'] ? 'draft' : 'wait', before = null, after = null, oils = null, skdraft = null;
    let draft = J('草稿.json');
    if (meta.type === 'skin') { try { before = JSON.parse(T('before.txt') || 'null'); } catch (e) {} try { after = JSON.parse(T('after.txt') || 'null'); } catch (e) {} if (st === 'wait') st = !before ? 'collect' : !after ? 'pre' : 'wait'; }
    if (meta.type === 'inbody' && st !== 'sent') st = ibFull_(ibNums_((draft || {}).after)) ? 'draft' : 'pre';
    if ((meta.type === 'soul' || meta.type === 'oil100') && st === 'wait' && !map['ready.txt']) st = 'collect';
    if (meta.type === 'oil100') { try { oils = JSON.parse(T('oils.txt') || 'null'); } catch (e) {} }
    if (meta.type === 'oil100' && st === 'draft' && draft && draft.cardUrl && !draft.cardId) draft = deskCardPull_(f, draft);
    if (meta.type === 'skin' && st !== 'sent') { try { skdraft = JSON.parse(T('skdraft.txt') || 'null'); } catch (e) {} }
    const row = {id: f.getId(), meta: meta, status: st, files: names.filter(function (n) { return !/\.json$/.test(n); }), before: before, after: after, oils: oils, skdraft: skdraft,
      draft: draft, sent: st === 'sent' ? J('已送出.json') : null, url: f.getUrl()};
    if (st === 'sent') { try { cache.put(ck, JSON.stringify(row), 21600); } catch (e) {} }
    out.push(row);
  }
  return out.sort(function (a, b) { return a.meta.created < b.meta.created ? 1 : -1; }).slice(0, 40);
}
